  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);
  const beforeProject = requireFound(
    await projectRepo.findProjectById(input.orgId, before.projectId),
    "Project",
    before.projectId,
  );
  assertProjectNotArchivedForIssue(before.id, beforeProject);

  const after = await issueRepo.updateIssue(input);

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
